ILineSource source = new FixedLines();
ILineSource filtered = new ContainsFilter(source, "C#");
Console.WriteLine(string.Join(" | ", filtered.Read()));

interface ILineSource { IEnumerable<string> Read(); }
class FixedLines : ILineSource
{
    public IEnumerable<string> Read() => new[] { "Học C#", "Học SQL", "Ôn C#" };
}
class ContainsFilter : ILineSource
{
    private readonly ILineSource inner;
    private readonly string keyword;
    public ContainsFilter(ILineSource inner, string keyword)
    { this.inner = inner; this.keyword = keyword; }
    public IEnumerable<string> Read() => inner.Read().Where(x => x.Contains(keyword, StringComparison.Ordinal));
}

