string[] input={"C#","SQL","C# nâng cao"};
Console.WriteLine(string.Join(",",Filter(input,"C#")));
Console.WriteLine(string.Join(",",new Search(new FixedSource(input)).Find("C#")));
try{new Search(new BrokenSource()).Find("C#").ToArray();}
catch(NotSupportedException){Console.WriteLine("vi phạm contract đọc");}
static IEnumerable<string> Filter(IEnumerable<string> lines,string key)=>lines.Where(s=>s.Contains(key,StringComparison.Ordinal));
interface IReadSource{IEnumerable<string> Read();}
class FixedSource(string[] lines):IReadSource{public IEnumerable<string> Read()=>lines;}
class BrokenSource:IReadSource{public IEnumerable<string> Read()=>throw new NotSupportedException();}
class Search(IReadSource source){public IEnumerable<string> Find(string key)=>source.Read().Where(s=>s.Contains(key,StringComparison.Ordinal));}

